import{_ as e,o as t,c as s,a3 as d}from"./chunks/framework.C6R8kWFE.js";const k=JSON.parse('{"title":"升级与迁移","description":"","frontmatter":{},"headers":[],"relativePath":"backend/upgrade.md","filePath":"backend/upgrade.md","lastUpdated":1791101145000}'),i={name:"backend/upgrade.md"};function n(o,a,r,l,p,c){return t(),s("div",null,[...a[0]||(a[0]=[d(`<h1 id="升级与迁移" tabindex="-1">升级与迁移 <a class="header-anchor" href="#升级与迁移" aria-label="Permalink to &quot;升级与迁移&quot;">​</a></h1><p>BasicApp 已接入 <a href="https://framework.docs.xihanfun.com/guide/upgrade" target="_blank" rel="noreferrer">XiHan.Framework.Upgrade</a> 的版本状态、迁移台账、多租户分发、租约锁与维护模式扩展，并在 <code>WebHost/UpdateScripts</code> 保存前向 SQL 脚本。<code>XiHan:Upgrade:EnableAutoCheckOnStartup</code> 为 <code>true</code> 时，<strong>应用启动会自动执行待执行的脚本</strong>，失败即中断启动。</p><h2 id="当前结论" tabindex="-1">当前结论 <a class="header-anchor" href="#当前结论" aria-label="Permalink to &quot;当前结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>当前状态</th></tr></thead><tbody><tr><td>Framework Upgrade 模块与引擎</td><td>已注册</td></tr><tr><td><code>SysVersion</code> 版本状态</td><td>已落库，每个数据库各自维护</td></tr><tr><td><code>SysMigrationHistory</code> 台账存储与查询页</td><td>已接线；每执行一个脚本记一条</td></tr><tr><td>文件系统脚本发现</td><td>已接入，目录为 <code>UpdateScripts/&lt;版本&gt;/</code></td></tr><tr><td>平台库 + 独立租户库分发</td><td>已实现</td></tr><tr><td>数据库租约锁</td><td>已实现</td></tr><tr><td>维护模式中间件</td><td>已实现</td></tr><tr><td>启动时自动执行 SQL</td><td><strong><code>EnableAutoCheckOnStartup=true</code> 时执行</strong>；框架缺省为 <code>true</code>，开发配置也写的是 <code>true</code></td></tr><tr><td>新建库登记基线</td><td>本次启动从零建出的平台库、<code>InitializeDatabase</code> 新建的独立库，建好即登记为最新脚本版本，不补跑历史脚本</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">启动即迁移，失败即中断</p><p>启动时有两个执行点，都调用 <code>IUpgradeEngine.ExecuteAsync()</code>、都以 <code>EnableAutoCheckOnStartup</code> 为开关：</p><ol><li><strong>数据库初始化的升级段</strong>：<code>SaasSchemaUpgrader</code> 实现框架的 <code>IDbSchemaUpgrader</code>，<code>DbInitializer</code> 按「建库建表 → 升级脚本 → 播种」三段执行，让存量表的新列在种子读写之前补齐。这一段只在 <code>EnableDbInitialization</code> 与 <code>EnableTableInitialization</code> 都开启时运行。</li><li><strong>应用初始化之后</strong>：<code>XiHanUpgradeModule.OnPostApplicationInitializationAsync</code> 先确保版本行存在，再执行一次引擎。数据库初始化关闭时由这里执行；第 1 段已经升级过时这里版本已是最新，直接空转。</li></ol><p>两处在引擎返回失败时都抛出「数据库升级失败，已中断启动」，应用不会带着半套表结构对外服务。不希望应用启动时改库，就把 <code>EnableAutoCheckOnStartup</code> 设为 <code>false</code>，由发布流程先执行脚本再启动应用。</p></div><h2 id="代码落点" tabindex="-1">代码落点 <a class="header-anchor" href="#代码落点" aria-label="Permalink to &quot;代码落点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职责</th><th>位置 / 类型</th></tr></thead><tbody><tr><td>框架模块</td><td><code>XiHanBasicAppCoreModule</code> 依赖 <code>XiHanUpgradeModule</code></td></tr><tr><td>版本与台账存储</td><td><code>SaasUpgradeVersionStore</code></td></tr><tr><td>数据库租约锁</td><td><code>SaasUpgradeLockProvider</code></td></tr><tr><td>多租户列表</td><td><code>SaasUpgradeTenantProvider</code></td></tr><tr><td>SQL 执行</td><td><code>SaasUpgradeMigrationExecutor</code></td></tr><tr><td>初始化升级段</td><td><code>SaasSchemaUpgrader</code>（<code>IDbSchemaUpgrader</code>：登记新库基线，按开关执行引擎）</td></tr><tr><td>维护模式</td><td><code>BasicAppUpgradeMaintenanceModeManager</code> + <code>MaintenanceModeMiddleware</code></td></tr><tr><td>脚本目录</td><td><code>backend/src/main/XiHan.BasicApp.WebHost/UpdateScripts</code></td></tr><tr><td>版本页面</td><td><code>/setting/version</code></td></tr><tr><td>升级记录页面</td><td><code>/log/migration</code></td></tr></tbody></table><p>BasicApp 在 <code>AddSaasDomainServices()</code> 中注册四个数据库适配器，使单服务解析优先使用业务实现：版本与台账写入业务库，SQL 由当前租户上下文解析出的 SqlSugar 客户端执行。</p><h2 id="全新数据库与存量数据库" tabindex="-1">全新数据库与存量数据库 <a class="header-anchor" href="#全新数据库与存量数据库" aria-label="Permalink to &quot;全新数据库与存量数据库&quot;">​</a></h2><p>两条路径职责不同：</p><table tabindex="0"><thead><tr><th>场景</th><th>机制</th><th>负责内容</th></tr></thead><tbody><tr><td>全新数据库</td><td>SqlSugar CodeFirst + Seeder</td><td>建库、建表、基础数据（演示数据按开关）</td></tr><tr><td>存量数据库</td><td>Upgrade + <code>UpdateScripts</code></td><td>增删列、索引变化、数据修复与版本推进</td></tr></tbody></table><p><code>DbInitializer</code> 对已存在的表不会自动补列。实体结构变更如果只改 C#、不写前向 SQL，存量库会在查询时出现 <code>column does not exist</code> 一类错误。</p><h2 id="脚本约定" tabindex="-1">脚本约定 <a class="header-anchor" href="#脚本约定" aria-label="Permalink to &quot;脚本约定&quot;">​</a></h2><p>目录结构是<strong>一个版本一个子目录</strong>（框架的 <code>FileSystemUpgradeScriptProvider</code> 只扫子目录），当前形如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UpdateScripts/</span></span>
<span class="line"><span>├── 3.10.0/3.10.0.sql</span></span>
<span class="line"><span>├── 3.10.1/3.10.1.sql</span></span>
<span class="line"><span>├── …</span></span>
<span class="line"><span>├── 5.4.0/</span></span>
<span class="line"><span>│   ├── 5.4.0-page-codes.sql</span></span>
<span class="line"><span>│   └── 5.4.0.sql</span></span>
<span class="line"><span>├── 5.6.0/5.6.0.sql</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p>规则：</p><ol><li>目录名即版本号，如 <code>UpdateScripts/5.6.1/5.6.1.sql</code>。只有高于库中 <code>DbVersion</code> 的版本会执行，与程序版本 <code>backend/props/version.props</code> 无关。</li><li>当前脚本使用 <strong>PostgreSQL 方言</strong>；文档中的 MySQL / MariaDB 支持主要指 ORM 与首次 CodeFirst，不代表现有升级脚本可直接跨库运行。引擎不区分方言，会把脚本原样交给当前库执行：非 PostgreSQL 的存量库开着 <code>EnableAutoCheckOnStartup</code> 升级时，<code>DO $$ … $$</code> 这类 PostgreSQL 专有语法会执行失败并中断启动，需要自备对应方言的脚本，或关掉自动升级另行处理。</li><li>PostgreSQL 标识符使用小写且不加引号，匹配 SqlSugar 实际创建的表列名。</li><li>尽量用 <code>IF EXISTS</code> / <code>IF NOT EXISTS</code> 写成可重试脚本。</li><li>一个版本内若存在多个脚本，引擎按脚本名排序；版本之间按语义版本升序执行。</li><li>先在生产数据副本验证脚本、备份与回滚方案，再发布应用。</li></ol><p>示例：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 5.6.1/5.6.1.sql</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sys_example</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remark </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ix_sys_example_tenant_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sys_example (tenant_id);</span></span></code></pre></div><h2 id="引擎执行流程" tabindex="-1">引擎执行流程 <a class="header-anchor" href="#引擎执行流程" aria-label="Permalink to &quot;引擎执行流程&quot;">​</a></h2><p>启动时的两个执行点调用的是同一台 <code>UpgradeEngine</code>，它对每个目标数据库执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解析应用版本与脚本</span></span>
<span class="line"><span>  → 读取/创建 SysVersion</span></span>
<span class="line"><span>  → 比较 DbVersion 与最新脚本版本</span></span>
<span class="line"><span>  → 获取数据库租约锁</span></span>
<span class="line"><span>  → 标记 IsUpgrading</span></span>
<span class="line"><span>  → 进入维护模式</span></span>
<span class="line"><span>  → 按版本和脚本名执行未成功记录过的脚本</span></span>
<span class="line"><span>  → 写 SysMigrationHistory 并推进 DbVersion</span></span>
<span class="line"><span>  → 更新 AppVersion</span></span>
<span class="line"><span>  → 退出维护模式并释放锁</span></span></code></pre></div><p><code>HasMigrationHistoryAsync(version, scriptName)</code> 只跳过已有<strong>成功</strong>记录的脚本；失败记录不会阻止下一次重试。</p><h3 id="多租户" tabindex="-1">多租户 <a class="header-anchor" href="#多租户" aria-label="Permalink to &quot;多租户&quot;">​</a></h3><p><code>EnableMultiTenantIsolation=true</code> 时，目标顺序是：</p><ol><li>平台库；</li><li><code>IsolationMode=Database</code> 且 <code>ConfigStatus=Configured</code> 的租户独立库。</li></ol><p>字段隔离租户与平台共库，不重复执行。每个独立库都有自己的 <code>SysVersion</code> 与 <code>SysMigrationHistory</code>，数据库版本可以独立追踪。</p><p>新建的库不补跑历史脚本：本次启动从零建出全部实体表的平台库（<code>SaasSchemaUpgrader</code> 按 <code>DbSchemaUpgradeContext.IsFresh</code> 判定）与 <code>InitializeDatabase</code> 新建的独立库，建好即通过 <code>IUpgradeEngine.BaselineAsync</code> 登记为最新脚本版本。独立库里只有租户库实体的表，脚本改平台库表（<code>[PlatformDataSource]</code> 实体）的语句要先判表存在，见 <code>UpdateScripts/README.md</code>。</p><h3 id="租约锁" tabindex="-1">租约锁 <a class="header-anchor" href="#租约锁" aria-label="Permalink to &quot;租约锁&quot;">​</a></h3><p><code>SaasUpgradeLockProvider</code> 通过条件更新 <code>SysVersion.IsUpgrading</code> 抢占执行权，并用 <code>UpgradeStartTime + LockExpirySeconds</code> 回收崩溃节点遗留的锁。它不是 Redis 锁，也不是 PostgreSQL 会话级建议锁。</p><p><code>PrimaryNodeName</code> 非空时，只有节点名完全匹配的实例会执行；留空时所有节点均可竞争数据库租约。<code>NodeName</code> 留空则由机器名与应用实例 ID 组合生成。</p><p>非主节点、以及没抢到租约的节点<strong>不会等待</strong>：引擎直接返回「等待升级 / 锁已被占用」，这不算失败，该节点照常完成启动。多副本同时发布时，要靠发布编排保证升级节点完成之前其它副本不接流量。</p><h3 id="维护模式" tabindex="-1">维护模式 <a class="header-anchor" href="#维护模式" aria-label="Permalink to &quot;维护模式&quot;">​</a></h3><p>引擎进入维护模式后，本节点的大部分请求返回：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">503</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;系统正在升级维护，请稍后重试。&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>响应带 <code>Retry-After: 30</code>。<code>/health</code> 与 <code>/.well-known/</code> 被放行，保证编排探针和 OIDC 发现/JWKS 可继续访问。</p><div class="warning custom-block"><p class="custom-block-title">维护状态只在当前进程内生效</p><p><code>MaintenanceModeState</code> 是进程内单例。多副本部署时，执行迁移的节点进入维护模式，不会自动让其它节点一起停流。若迁移与旧版本不兼容，应在网关或发布编排层统一摘流，不能只依赖该中间件。</p></div><h2 id="执行方式怎么选" tabindex="-1">执行方式怎么选 <a class="header-anchor" href="#执行方式怎么选" aria-label="Permalink to &quot;执行方式怎么选&quot;">​</a></h2><p>当前默认是第一种；要换成别的方式，先关掉 <code>EnableAutoCheckOnStartup</code>：</p><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>注意</th></tr></thead><tbody><tr><td>启动时自动执行（当前默认，<code>EnableAutoCheckOnStartup=true</code>）</td><td>单体或单副本先行的发布</td><td>失败即中断启动；多副本时非主节点和抢不到租约的节点不等待，需编排层控制放流</td></tr><tr><td>发布流水线独立迁移步骤（<code>EnableAutoCheckOnStartup=false</code>）</td><td>多副本生产</td><td>迁移成功后再放应用流量，边界最清晰；仓库没有现成的独立迁移命令，需要自建</td></tr><tr><td>管理端调用 <code>IUpgradeCoordinator.StartAsync()</code></td><td>人工触发</td><td>BasicApp 没有接这个入口；协调器后台运行且只记日志，不能形成启动失败门禁</td></tr></tbody></table><p>不要在多个位置同时触发。无论选择哪种方式，都要保证只有一个可审计入口，并测试多节点竞争、脚本失败、进程中断和重复执行。</p><h2 id="页面与权限" tabindex="-1">页面与权限 <a class="header-anchor" href="#页面与权限" aria-label="Permalink to &quot;页面与权限&quot;">​</a></h2><ul><li><code>/setting/version</code>：查看 <code>SysVersion</code>，只读；写端点已移除。</li><li><code>/log/migration</code>：查看脚本版本、脚本名、成功状态、执行时间、节点与错误信息。</li><li>两页读取都要求 <code>saas:version:read</code>；版本列表导出使用 <code>saas:version:export</code>。</li></ul><p>页面展示的是当前租户上下文解析到的数据库状态。排查独立租户库时要先确认当前租户，不能只看平台库记录。</p><h2 id="发布检查清单" tabindex="-1">发布检查清单 <a class="header-anchor" href="#发布检查清单" aria-label="Permalink to &quot;发布检查清单&quot;">​</a></h2><ol><li>抬高应用版本，并新增同版本或更低的必要 SQL 脚本。</li><li>确认脚本为 PostgreSQL 小写无引号标识符，且可安全重试。</li><li>在生产副本依次验证升级、重复执行和失败恢复。</li><li>备份平台库与全部数据库隔离租户库。</li><li>确认生产环境的 <code>EnableAutoCheckOnStartup</code>：缺省为 <code>true</code>，新版本启动即执行脚本；关掉时要在启动前由发布流程完成迁移。</li><li>多节点发布时确认 <code>NodeName</code> / <code>PrimaryNodeName</code>、租约时长与统一摘流方案。</li><li>升级后检查 <code>/setting/version</code>、<code>/log/migration</code>、应用日志与关键业务查询。</li></ol><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./database">数据库配置</a>：CodeFirst、连接与存量结构变更</li><li><a href="./health-observability">健康检查与可观测性</a>：维护窗口仍放行的 <code>/health</code></li><li><a href="./../configuration#xihan-upgrade">配置参考</a>：<code>XiHan:Upgrade</code> 字段</li><li><a href="./../deployment">部署</a>：发布、进程守护与生产配置</li><li><a href="https://framework.docs.xihanfun.com/guide/upgrade" target="_blank" rel="noreferrer">Framework 升级与迁移</a>：引擎抽象与通用流程</li></ul>`,48)])])}const g=e(i,[["render",n]]);export{k as __pageData,g as default};
